package com.ilia.gikashvili.archmain.admin.service;
import java.util.UUID;import org.springframework.stereotype.Component;import org.springframework.transaction.event.TransactionalEventListener;
@Component public class RegistrationJobs {public record Registered(UUID userId){} private final BackgroundJobService jobs;private final org.springframework.transaction.support.TransactionTemplate tx;public RegistrationJobs(BackgroundJobService j,org.springframework.transaction.PlatformTransactionManager tm){jobs=j;tx=new org.springframework.transaction.support.TransactionTemplate(tm);tx.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_REQUIRES_NEW);} @TransactionalEventListener public void registered(Registered event){UUID id=tx.execute(s->jobs.welcome(event.userId()));jobs.execute(id);}}
